package it.carmine.streamplayer;
import android.content.Intent;import android.widget.FrameLayout;import org.json.JSONObject;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;import static org.robolectric.Shadows.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class CbNativeNavigationTest {
 @Before public void clear(){VodSettings.prefs(RuntimeEnvironment.getApplication()).edit().clear().putString("catalogSource","cb01").commit();VodSession.reset();}
 @Test public void cbSearchKeepsNativeGridAndDoesNotRedirect(){Intent intent=new Intent(RuntimeEnvironment.getApplication(),VodCatalogueActivity.class).putExtra("searchPage",true).putExtra("startMode",1);try(ActivityController<VodCatalogueActivity> c=Robolectric.buildActivity(VodCatalogueActivity.class,intent).create().start().resume()){assertFalse(c.get().isFinishing());assertNotNull(c.get().getWindow().getDecorView().findViewWithTag("vodGrid"));assertNull(shadowOf(c.get()).getNextStartedActivity());}}
 @Test public void sourceDialogLoadsExactPosterPageWithoutLaunchingAnotherActivity()throws Exception{try(ActivityController<VodActivity> c=Robolectric.buildActivity(VodActivity.class).create().start().resume()){VodActivity a=c.get();String exact="https://cb01uno.wiki/123-selected-film/";VodSource.Title t=new VodSource.Title(new JSONObject().put("id","123").put("name","Selected film").put("_web_page",exact),"");FrameLayout root=(FrameLayout)a.getWindow().getDecorView().findViewWithTag("vodHomeScroll").getParent();CbSourcesDialog d=CbSourcesDialog.show(a,root,t,VodSession.catalogue(a),-1);assertNull(shadowOf(a).getNextStartedActivity());android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing());boolean found=false;for(int i=0;i<root.getChildCount();i++)if(root.getChildAt(i) instanceof android.webkit.WebView){android.webkit.WebView web=(android.webkit.WebView)root.getChildAt(i);if(exact.equals(shadowOf(web).getLastLoadedUrl()))found=true;}assertTrue(found);d.close();assertFalse(dialog.isShowing());}}
}
